mapper.select:
SELECT a.asgn_id,a.dev_id,d.dev_nm,d.emp_se_cd,a.prj_id,p.prj_nm,a.end_dt,u.bill_untprc_amt
FROM asgn.asgn a
JOIN mst.dev d ON d.dev_id=a.dev_id
JOIN prj.prj p ON p.prj_id=a.prj_id
LEFT JOIN LATERAL (
  SELECT h.bill_untprc_amt FROM asgn.untprc_hist h
  WHERE h.asgn_id=a.asgn_id AND h.aply_bgn_dt <= #{today}
  ORDER BY h.aply_bgn_dt DESC LIMIT 1
) u ON true
WHERE a.asgn_stts_cd='ACTIVE' AND a.asgn_se_cd!='FREE'
  AND p.prj_stts_cd='RUN' AND p.cntrct_ty_cd IN ('MO','DP')
  AND a.bgn_dt <= #{today} AND a.end_dt >= #{today} AND a.end_dt <= #{through}
AND d.emp_se_cd=#{empType}
AND a.prj_id=#{projectId}
ORDER BY a.asgn_id
